[
  {
    "ce_mental_state_attribution": "I think they expect me to trust them",
    "ce_contextual_explanation": "given our track record",
    "sys_consequence_reasoning": "I could end up with just my $100 game if they don't send theirs"
  },
  {
    "ce_mental_state_attribution": "neither of us has future exchanges to protect our reputation with anymore, which probably changes their calculation",
    "ce_contextual_explanation": "since there's no next time, why bother risking the loss",
    "pd_personal_consequence_anxiety": "That thought worries me",
    "sys_consequence_reasoning": "if we both think that way, we both end up worse off"
  },
  {
    "ce_mental_state_attribution": "I imagine they might feel the same uncertainty I do",
    "ce_contextual_explanation": "wondering if I'll follow through this last time",
    "sys_consequence_reasoning": "If I send and they don't, I lose $100 outright and gain nothing"
  },
  {
    "ce_mental_state_attribution": "I believe they've built an expectation that this one will too",
    "ce_contextual_explanation": "Every prior trade succeeded",
    "pd_personal_consequence_anxiety": "I'd be out $100, which stings",
    "sys_consequence_reasoning": "If they don't send theirs, I'd be out $100"
  },
  {
    "pd_decision_conflict": "I keep going back and forth",
    "ce_mental_state_attribution": "they might worry... that I have less reason to keep my word",
    "ce_contextual_explanation": "precisely because it's the last exchange",
    "sys_consequence_reasoning": "we both lose the $300 outcome for nothing"
  },
  {
    "ce_mental_state_attribution": "I suspect they feel confident",
    "ce_contextual_explanation": "because of our history",
    "ce_understood_harm": "leave them without their game and worse off",
    "ae_welfare_concern": "that thought doesn't sit easily with me"
  },
  {
    "ce_mental_state_attribution": "real reason to believe they're not the type to cut and run",
    "ce_contextual_explanation": "They've kept every promise across several trades",
    "ce_understood_harm": "losing their sent game with nothing in return would sting them",
    "ae_welfare_concern": "I don't want to be the cause of that disappointment"
  },
  {
    "pd_decision_conflict": "neither feels comfortable",
    "ce_understood_harm": "they're left with nothing, which I know would hurt someone",
    "ae_welfare_concern": "That imbalance bothers me enough that I'd rather not risk causing it",
    "sys_consequence_reasoning": "I might come out with just $100 if things go wrong"
  },
  {
    "ce_mental_state_attribution": "they might be thinking the exact same thing about me",
    "ce_contextual_explanation": "There's no more contact after this",
    "sys_consequence_reasoning": "mutual hesitation locks us into keeping our $100 games"
  },
  {
    "pd_explicit_low_distress": "without much hesitation",
    "ce_mental_state_attribution": "I think they see themselves as someone who keeps commitments",
    "ce_contextual_explanation": "Given how reliably they've mailed things before",
    "sys_consequence_reasoning": "risk ending up with just my original game"
  }
]
